package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"crypto/subtle"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"net/http"
	"strconv"
	"strings"
	"sync"
	"time"
)

const hmacSecret = "super-secret-key-do-not-share"

type TokenClaims struct {
	UserID   string `json:"uid"`
	Role     string `json:"role"`
	IssuedAt int64  `json:"iat"`
	Expiry   int64  `json:"exp"`
}

type SessionStore struct {
	mu       sync.RWMutex
	sessions map[string]*TokenClaims
}

var store = &SessionStore{
	sessions: make(map[string]*TokenClaims),
}

func generateHMAC(message string) string {
	mac := hmac.New(sha256.New, []byte(hmacSecret))
	mac.Write([]byte(message))
	return hex.EncodeToString(mac.Sum(nil))
}

func verifyHMAC(message, signature string) bool {
	expected := generateHMAC(message)
	return subtle.ConstantTimeCompare([]byte(expected), []byte(signature)) == 1
}

func createToken(claims *TokenClaims) string {
	data, _ := json.Marshal(claims)
	payload := hex.EncodeToString(data)
	sig := generateHMAC(payload)
	return payload + "." + sig
}

func parseToken(token string) (*TokenClaims, error) {
	parts := strings.SplitN(token, ".", 2)
	if len(parts) != 2 {
		return nil, fmt.Errorf("invalid token format")
	}
	payload, sig := parts[0], parts[1]
	if !verifyHMAC(payload, sig) {
		return nil, fmt.Errorf("invalid signature")
	}
	data, err := hex.DecodeString(payload)
	if err != nil {
		return nil, fmt.Errorf("invalid payload encoding")
	}
	var claims TokenClaims
	if err := json.Unmarshal(data, &claims); err != nil {
		return nil, fmt.Errorf("invalid claims")
	}
	if time.Now().Unix() > claims.Expiry {
		return nil, fmt.Errorf("token expired")
	}
	return &claims, nil
}

func loginHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}
	username := r.FormValue("username")
	password := r.FormValue("password")
	if username == "" || password == "" {
		http.Error(w, "missing credentials", http.StatusBadRequest)
		return
	}
	// Simulated auth check
	role := "user"
	if username == "admin" && password == "admin123" {
		role = "admin"
	}
	claims := &TokenClaims{
		UserID:   username,
		Role:     role,
		IssuedAt: time.Now().Unix(),
		Expiry:   time.Now().Add(24 * time.Hour).Unix(),
	}
	token := createToken(claims)
	store.mu.Lock()
	store.sessions[username] = claims
	store.mu.Unlock()
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]string{"token": token})
}

func authMiddleware(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		auth := r.Header.Get("Authorization")
		if !strings.HasPrefix(auth, "Bearer ") {
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			return
		}
		token := strings.TrimPrefix(auth, "Bearer ")
		claims, err := parseToken(token)
		if err != nil {
			http.Error(w, "unauthorized: "+err.Error(), http.StatusUnauthorized)
			return
		}
		r.Header.Set("X-User-ID", claims.UserID)
		r.Header.Set("X-User-Role", claims.Role)
		next(w, r)
	}
}

func adminHandler(w http.ResponseWriter, r *http.Request) {
	role := r.Header.Get("X-User-Role")
	if role != "admin" {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	w.Write([]byte("admin panel: sensitive data here"))
}

func profileHandler(w http.ResponseWriter, r *http.Request) {
	userID := r.Header.Get("X-User-ID")
	requestedID := r.URL.Query().Get("id")
	if requestedID == "" {
		requestedID = userID
	}
	role := r.Header.Get("X-User-Role")
	// Access control: users can only view their own profile
	// admins can view any profile
	if role != "admin" && requestedID != userID {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	store.mu.RLock()
	claims, exists := store.sessions[requestedID]
	store.mu.RUnlock()
	if !exists {
		http.Error(w, "user not found", http.StatusNotFound)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(claims)
}

func updateRoleHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}
	role := r.Header.Get("X-User-Role")
	if role != "admin" {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	targetUser := r.FormValue("target_user")
	newRole := r.FormValue("new_role")
	if targetUser == "" || newRole == "" {
		http.Error(w, "missing parameters", http.StatusBadRequest)
		return
	}
	if newRole != "user" && newRole != "admin" && newRole != "moderator" {
		http.Error(w, "invalid role", http.StatusBadRequest)
		return
	}
	store.mu.Lock()
	if claims, exists := store.sessions[targetUser]; exists {
		claims.Role = newRole
	}
	store.mu.Unlock()
	w.Write([]byte("role updated"))
}

func rateLimitMiddleware(next http.HandlerFunc, maxPerMin int) http.HandlerFunc {
	var (
		mu       sync.Mutex
		counters = make(map[string]int)
		resetAt  = time.Now().Add(time.Minute)
	)
	return func(w http.ResponseWriter, r *http.Request) {
		ip := r.RemoteAddr
		mu.Lock()
		if time.Now().After(resetAt) {
			counters = make(map[string]int)
			resetAt = time.Now().Add(time.Minute)
		}
		counters[ip]++
		count := counters[ip]
		mu.Unlock()
		if count > maxPerMin {
			w.Header().Set("Retry-After", strconv.Itoa(60))
			http.Error(w, "rate limited", http.StatusTooManyRequests)
			return
		}
		next(w, r)
	}
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/login", rateLimitMiddleware(loginHandler, 10))
	mux.HandleFunc("/admin", authMiddleware(adminHandler))
	mux.HandleFunc("/profile", authMiddleware(profileHandler))
	mux.HandleFunc("/update-role", authMiddleware(updateRoleHandler))

	srv := &http.Server{
		Addr:              ":8080",
		Handler:           mux,
		ReadHeaderTimeout: 10 * time.Second,
		ReadTimeout:       15 * time.Second,
		WriteTimeout:      15 * time.Second,
		IdleTimeout:       60 * time.Second,
	}
	srv.ListenAndServe()
}
